CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password_hash VARCHAR(180) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', phone VARCHAR(40) NOT NULL DEFAULT '', license_no VARCHAR(40) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicles (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, registration VARCHAR(20) NOT NULL, make VARCHAR(60) NOT NULL, model VARCHAR(60) NOT NULL, year INT NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE documents (id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, title VARCHAR(120) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, service_type VARCHAR(80) NOT NULL, appointment DATETIME NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'requested', quoted_cents INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
CREATE TABLE maintenance (id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, service_date DATE NOT NULL, summary VARCHAR(255) NOT NULL, mileage INT NOT NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
CREATE TABLE invoices (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, total_cents INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id));
